impl From<&str> for SdkVersionLanguage {
    fn from(value: &str) -> Self {
        match value {
            "typescript" => Self::Typescript,
            "python" => Self::Python,
            "cli" => Self::Cli,
            "csharp" => Self::Csharp,
            "java" => Self::Java,
            "ruby" => Self::Ruby,
            "php" => Self::Php,
            "go" => Self::Go,
            "rust" => Self::Rust,
            "kotlin" => Self::Kotlin,
            "swift" => Self::Swift,
            "cpp" => Self::Cpp,
            "dart" => Self::Dart,
            other => Self::Unknown(other.to_owned()),
        }
    }
}
